class Cart {
  #items = [];

  add(name, price) {
    this.#items.push({ name, price });
  }

  remove(name) {
    this.#items = this.#items.filter((item) => item.name !== name);
  }

  get total() {
    return this.#items.reduce((sum, item) => sum + item.price, 0);
  }

  get count() {
    return this.#items.length;
  }
}

const cart = new Cart();
cart.add('Notebook', 12);
cart.add('Pen', 3);

console.log(cart.count);  // 2
console.log(cart.total);  // 15

cart.remove('Pen');
console.log(cart.total);  // 12 — recomputed, cannot be stale

